import { ApiPropertyOptional } from '@nestjs/swagger';

import {
  IsDateString,
  IsOptional,
  IsString,
  MaxLength,
  MinLength,
} from 'class-validator';

/**
 * REST request DTO for physically boarding a passenger.
 *
 * The Journey Boarding and participant IDs come from route parameters.
 * Correlation metadata is generated by the backend.
 */
export class BoardPassengerDto {
  /**
   * Optional identifier of the command or event that caused this request.
   */
  @ApiPropertyOptional({
    description: 'Identifier of the command or event that caused this request.',
    example: 'cmd-01J8XYZABC',
    minLength: 1,
    maxLength: 200,
  })
  @IsOptional()
  @IsString()
  @MinLength(1)
  @MaxLength(200)
  causationId?: string;

  /**
   * Optional physical boarding timestamp.
   */
  @ApiPropertyOptional({
    description:
      'ISO-8601 timestamp representing when the passenger physically boarded.',
    example: '2026-08-19T06:45:00.000Z',
    format: 'date-time',
  })
  @IsOptional()
  @IsDateString()
  boardedAt?: string;
}

export default BoardPassengerDto;
